// Replace with real companies: name + homepage URL
return [
  { json: { azienda: 'COMPANY 1', sito: 'https://www.example-company-1.it' } },
  { json: { azienda: 'COMPANY 2', sito: 'https://www.example-company-2.it' } },
  { json: { azienda: 'COMPANY 3', sito: 'https://www.example-company-3.it' } }
];

const leads = $('Lista Lead').all();
return $input.all().map((item, i) => {
  const html = String(item.json.data || '');
  const text = html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 6000);
  return { json: { ...leads[i].json, testo_sito: text, sito_letto: text.length > 200 }, pairedItem: i };
});

const leads = $('Pulisci Testo').all();
return $input.all().map((item, i) => {
  let ai = {};
  try {
    ai = JSON.parse(item.json.choices[0].message.content);
  } catch (e) {
    ai = { fit_score: 0, cosa_fa: 'errore lettura AI', email: '' };
  }
  const lead = leads[i].json;
  const domain = String(lead.sito || '').replace(/^https?:\/\//i, '').replace(/^www\./i, '').split('/')[0];
  return { json: {
    azienda: lead.azienda,
    sito: lead.sito,
    dominio: domain,
    sito_letto: lead.sito_letto,
    cosa_fa: ai.cosa_fa || '',
    settore: ai.settore || '',
    fit_score: Number(ai.fit_score) || 0,
    motivazione_fit: ai.motivazione_fit || '',
    angolo_pitch: ai.angolo_pitch || '',
    oggetto_email: ai.oggetto_email || '',
    email: ai.email || ''
  }, pairedItem: i };
});

